import sys


def main():
    data = sys.stdin.read().split()
    a, b = data[0], data[1]
    la, m = len(a), len(b)
    k = -(-m // la)
    text = a * (k + 1)
    fail = [0] * m
    j = 0
    for i in range(1, m):
        while j and b[i] != b[j]:
            j = fail[j - 1]
        if b[i] == b[j]:
            j += 1
        fail[i] = j
    j = 0
    pos = -1
    for i, ch in enumerate(text):
        while j and ch != b[j]:
            j = fail[j - 1]
        if ch == b[j]:
            j += 1
        if j == m:
            pos = i - m + 1
            break
    if pos < 0:
        print(-1)
    else:
        print(-(-(pos + m) // la))


